// Parse the command from query parameters
const query = $input.first().json.query || {};
const command = query.command || 'help';
const chatId = query.chat_id || '__TELEGRAM_CHAT_ID__';

return [{
  json: {
    command: command.toLowerCase(),
    chatId: chatId
  }
}];

// Collect data from real APIs
const https = require('https');
const http = require('http');

function fetchData(url, headers) {
  return new Promise((resolve, reject) => {
    const urlObj = new URL(url);
    const options = {
      hostname: urlObj.hostname,
      port: urlObj.port,
      path: urlObj.pathname + urlObj.search,
      method: 'GET',
      headers: headers
    };

    const client = urlObj.protocol === 'https:' ? https : http;
    const req = client.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => data += chunk);
      res.on('end', () => {
        try {
          resolve(JSON.parse(data));
        } catch(e) {
          resolve(null);
        }
      });
    });
    req.on('error', reject);
    req.end();
  });
}

const RAPIDAPI_KEY = '__RAPIDAPI_KEY__';
const now = new Date();
const dateStr = now.toISOString().split('T')[0];

// Get football live
let footballMatches = [];
try {
  const footballData = await fetchData(
    'https://free-api-live-football-data.p.rapidapi.com/football-current-live',
    {'Content-Type': 'application/json', 'x-rapidapi-host': 'free-api-live-football-data.p.rapidapi.com', 'x-rapidapi-key': RAPIDAPI_KEY}
  );
  const live = footballData?.response?.live || [];
  footballMatches = live.slice(0, 5).map(m => ({
    matchId: `FOOTBALL-${m.id}`,
    homeTeam: m.home?.name || 'Unknown',
    awayTeam: m.away?.name || 'Unknown',
    league: 'Live Match',
    eventDate: dateStr,
    eventId: m.id,
    homeScore: m.home?.score || 0,
    awayScore: m.away?.score || 0,
    status: m.status?.scoreStr || 'Not started'
  }));
} catch(e) {}

// Get tennis live
let tennisMatches = [];
try {
  const tennisData = await fetchData(
    'https://tennisapi1.p.rapidapi.com/api/tennis/events/live',
    {'Content-Type': 'application/json', 'x-rapidapi-host': 'tennisapi1.p.rapidapi.com', 'x-rapidapi-key': RAPIDAPI_KEY}
  );
  const events = tennisData?.events || [];
  tennisMatches = events.slice(0, 5).map(e => ({
    matchId: `TENNIS-${e.id}`,
    player1: e.homeTeam?.name || 'Unknown',
    player2: e.awayTeam?.name || 'Unknown',
    tournament: e.tournament?.name || 'Unknown',
    eventDate: dateStr,
    eventId: e.id,
    status: e.status?.description || 'Not started'
  }));
} catch(e) {}

const output = {
  generatedAt: now.toISOString(),
  source: 'live_api',
  tennis: tennisMatches,
  football: footballMatches
};

const jsonString = JSON.stringify(output, null, 2);
const timestamp = now.toISOString().replace(/[-:]/g, '').replace(/\\..*/, '');
const filename = `matches_${timestamp}.json`;

return [{
  json: {
    data: jsonString,
    filename: filename,
    filepath: `/storage/matches/${filename}`,
    tennisCount: tennisMatches.length,
    footballCount: footballMatches.length
  }
}];

// Return help message
return [{
  json: {
    message: "🤖 BrainBets Bot Commands:

📊 /collect - Recolectar datos de partidos
🎯 /predict - Generar predicciones
✅ /validate - Validar predicciones
🔄 /pipeline - Ejecutar pipeline completo
❓ /help - Mostrar esta ayuda"
  }
}];
